package ncasa.notification.application;
import java.time.Clock;import java.util.UUID;import ncasa.notification.application.port.out.*;import ncasa.notification.domain.*;
public final class MarkNotificationReadUseCase{private final NotificationRepository notifications;private final HouseholdNotificationDirectoryPort households;private final Clock clock;public MarkNotificationReadUseCase(NotificationRepository n,HouseholdNotificationDirectoryPort h,Clock c){notifications=n;households=h;clock=c;}public NotificationView execute(Long account,UUID id){var value=notifications.findAccessible(new NotificationId(id),new AccountRef(account),NotificationAccess.households(households,account)).orElseThrow(NotificationNotFoundException::new);value.markRead(clock.instant());return NotificationView.from(notifications.save(value));}}
